93	    /** Separators (spaces, dashes and brackets) stripped from a telephone before parsing. */
94	    private static final Pattern TELEPHONE_SEPARATORS = Pattern.compile("[\\s()\\[\\]-]");
95	
96	    /** A valid E.164 body: a leading '+' followed by 8 to 15 digits. */
97	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
98	
99	    /** Common street-type abbreviations expanded (on upper-cased tokens) during address normalization. */
100	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
101	        "ST", "STREET",
102	        "RD", "ROAD",
103	        "AVE", "AVENUE");
104	
105	    /** Dedicated audit logger; a create side-effect is recorded here on success. */
106	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
107	
