153	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
154	        List<String> missingFields = new ArrayList<>();
155	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
156	            missingFields.add("firstName");
157	        }
158	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
159	            missingFields.add("lastName");
160	        }
161	        // Normalize the address up front; the required-field check rejects it when it is blank
162	        // after normalization (e.g. a whitespace-only value collapses to the empty string).
163	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
164	        if (!StringUtils.hasText(normalizedAddress)) {
165	            missingFields.add("address");
